INSERT INTO `pages` VALUES (3,NULL,'Struktur Organisasi','struktur-organisasi','<p><img src=\"data:image/png;base64,\" width=\"600\" height=\"1075\"></p>','SMK Fadris Tasikmalaya','','default','published','2026-03-25 06:23:52','2026-08-25 02:19:04');
INSERT INTO `pages` VALUES (5,NULL,'Visi & Misi','visi-misi','<p style=\"text-align: justify;\"><strong>Visi</strong></p>\r\n<blockquote>\r\n<p>Menjadi pusat keunggulan studi, amaliyah, dan terapi tasawuf yang kredibel berbasis&nbsp;nilai-nilai Tarekat Idrisiyyah tahun 2035</p>\r\n</blockquote>\r\n<p style=\"text-align: justify;\"><strong>Misi</strong></p>\r\n<ol style=\"list-style-type: lower-alpha; text-align: justify;\">\r\n<li>Pendidikan: Melahirkan kader ulama-intelektual profesional yang ahli di&nbsp;bidang Ilmu Tasawuf dan Tarekat.</li>\r\n<li>Penelitian: Mengembangkan pusat riset tasawuf klasik dan kontemporer&nbsp;sebagai solusi problematika umat modern.</li>\r\n<li>Praktik: Menstandarisasi praktik terapi tasawuf sebagai manifestasi&nbsp;kemanfaatan ilmu bagi kesehatan mental dan spiritual.</li>\r\n<li>Pengabdian: Mewujudkan transformasi sosial yang religius berbasis nilainilai Tarekat Idrisiyyah.</li>\r\n<li>Manajemen: Membangun tata kelola lembaga yang amanah, modern, dan<br>mandiri.</li>\r\n</ol>\r\n<p style=\"text-align: justify;\"><strong>Tujuan Ma&rsquo;had Aly Idrisiyyah</strong></p>\r\n<p style=\"text-align: justify;\">Untuk mewujudkan Visi 2035, Ma&rsquo;had Aly Idrisiyyah menetapkan target-target strategis&nbsp;sebagai berikut:</p>\r\n<ol style=\"list-style-type: lower-alpha;\">\r\n<li style=\"text-align: justify;\">Bidang Pendidikan (Ulama-Intelektual)\r\n<ol>\r\n<li>Menghasilkan lulusan yang memiliki kedalaman ilmu alat (kitab kuning) serta&nbsp;otoritas keilmuan di bidang Tasawuf dan Tarekat yang bersanad.</li>\r\n<li>Mewujudkan kurikulum integratif yang memadukan khazanah turats dengan&nbsp;metodologi akademik modern.</li>\r\n<li>Mencetak kader ulama yang mampu menjawab tantangan zaman dengan&nbsp;akhlakul karimah dan karakter kepemimpinan tarekat.</li>\r\n</ol>\r\n</li>\r\n<li style=\"text-align: justify;\">Bidang Penelitian (Riset Integratif)\r\n<ol>\r\n<li>Menghasilkan karya ilmiah, jurnal, dan buku di bidang tasawuf klasik maupun&nbsp;kontemporer yang diakui secara nasional dan internasional.</li>\r\n<li>Menjadikan Ma&rsquo;had Aly sebagai rujukan utama (reference center) dalam&nbsp;membedah problematika umat melalui kacamata Neosufisme.</li>\r\n<li>Mengembangkan pemikiran tasawuf yang aplikatif sebagai instrumen&nbsp;transformasi sosial dan intelektual.</li>\r\n</ol>\r\n</li>\r\n<li style=\"text-align: justify;\">Bidang Praktik &amp; Terapi (Kesehatan Mental-Spiritual)\r\n<ol>\r\n<li style=\"text-align: justify;\">Menyusun standar operasional dan modul pelatihan terapi tasawuf yang&nbsp;kredibel dan dapat dipertanggungjawabkan secara ilmiah maupun syar\'i.</li>\r\n<li style=\"text-align: justify;\">Melahirkan praktisi terapi tasawuf yang kompeten dalam menangani krisis&nbsp;spiritual dan gangguan kesehatan mental masyarakat modern.</li>\r\n<li style=\"text-align: justify;\">Mendirikan pusat layanan terapi tasawuf sebagai bentuk nyata \"<strong>Tasawuf&nbsp;Solutif</strong>\" bagi masyarakat luas.</li>\r\n</ol>\r\n</li>\r\n<li style=\"text-align: justify;\">Bidang Pengabdian (Transformasi Sosial)\r\n<ol>\r\n<li style=\"text-align: justify;\">Mengimplementasikan nilai-nilai Tarekat Idrisiyyah dalam bentuk aksi sosial&nbsp;yang mampu menggerakkan ekonomi, pendidikan, dan moralitas masyarakat.</li>\r\n<li style=\"text-align: justify;\">Membangun jejaring kemitraan yang luas dengan berbagai lembaga&nbsp;pemerintahan maupun swasta dalam program pemberdayaan umat yang&nbsp;religius.</li>\r\n<li style=\"text-align: justify;\">Menjadikan mahasantri sebagai agen perubahan yang aktif dalam pembinaan&nbsp;mental-spiritual di tengah masyarakat.</li>\r\n</ol>\r\n</li>\r\n<li style=\"text-align: justify;\">Bidang Manajemen (Tata Kelola Amanah)&nbsp;\r\n<ol>\r\n<li style=\"text-align: justify;\">Mewujudkan sistem tata kelola perguruan tinggi yang transparan, akuntabel,&nbsp;dan berbasis teknologi informasi (modern).</li>\r\n<li style=\"text-align: justify;\">Mencapai kemandirian ekonomi kelembagaan untuk mendukung&nbsp;keberlangsungan operasional pendidikan dan dakwah.</li>\r\n<li style=\"text-align: justify;\">Meningkatkan kualitas sumber daya manusia (dosen dan tenaga&nbsp;kependidikan) yang profesional dan berintegritas tinggi.</li>\r\n</ol>\r\n</li>\r\n</ol>','visi dan misi, tujuan dan strategi Ma\'had Aly Idrisiyyah','','default','published','2026-03-25 06:37:28','2026-08-25 02:19:04'),(6,NULL,'Profil Prodi','profil-prodi','<div style=\"font-family: \'Segoe UI\', Roboto, Arial, sans-serif; color: #333; max-width: 1000px; margin: 0 auto; line-height: 1.6; background-color: #ffffff; border: 1px solid #eee;\">\r\n<div style=\"background-color: #1b5e20; padding: 50px 20px; text-align: center; border-bottom: 5px solid #ffd700;\">\r\n<h1 style=\"color: #ffd700; text-transform: uppercase; letter-spacing: 3px; margin: 0; font-size: 24px;\">Program Studi Tasawuf wa Thoriqotuhu</h1>\r\n<div style=\"height: 2px; width: 100px; background: #ffd700; margin: 15px auto;\">&nbsp;</div>\r\n<p style=\"color: #e8f5e9; font-size: 14px; max-width: 700px; margin: 0 auto; font-style: italic;\">\"Membentuk Generasi Mutashowwif yang Berintelektual Tinggi, Berakhlaqul Karimah, dan Berpegang Teguh pada Sanad Keguruan.\"</p>\r\n</div>\r\n<div style=\"display: flex; flex-wrap: wrap; padding: 20px; gap: 20px; justify-content: center;\">\r\n<div style=\"flex: 1; min-width: 300px; background: #f1f8e9; padding: 25px; border-radius: 15px; border-left: 5px solid #1b5e20; box-shadow: 2px 2px 10px rgba(0,0,0,0.05);\">\r\n<h3 style=\"color: #1b5e20; margin-top: 0; display: flex; align-items: center;\"><span style=\"font-size: 24px; margin-right: 10px;\">👁️</span> VISI</h3>\r\n<p style=\"font-size: 14px; color: #444; text-align: justify;\">Menjadi Program Studi unggulan dalam kajian Tasawuf dan Thoriqah yang integratif, berbasis kearifan lokal, dan diakui di tingkat internasional pada tahun 2030.</p>\r\n</div>\r\n<div style=\"flex: 1; min-width: 300px; background: #fffde7; padding: 25px; border-radius: 15px; border-left: 5px solid #ffd700; box-shadow: 2px 2px 10px rgba(0,0,0,0.05);\">\r\n<h3 style=\"color: #856404; margin-top: 0; display: flex; align-items: center;\"><span style=\"font-size: 24px; margin-right: 10px;\">📜</span> MISI</h3>\r\n<ul style=\"font-size: 13px; color: #444; padding-left: 18px; margin: 0;\">\r\n<li style=\"margin-bottom: 8px;\">Menyelenggarakan pendidikan Tasawuf yang bersanad dan aplikatif.</li>\r\n<li style=\"margin-bottom: 8px;\">Mengembangkan riset mendalam tentang jaringan Thoriqah di Nusantara.</li>\r\n<li style=\"margin-bottom: 8px;\">Mengabdi kepada masyarakat melalui bimbingan spiritual dan sosial.</li>\r\n</ul>\r\n</div>\r\n</div>\r\n<div style=\"padding: 30px 20px; background: #fafafa;\">\r\n<h2 style=\"text-align: center; color: #1b5e20; font-size: 20px; margin-bottom: 30px;\">Kenapa Memilih Prodi Ini?</h2>\r\n<div style=\"display: flex; flex-wrap: wrap; gap: 15px; justify-content: center;\">\r\n<div style=\"width: 220px; text-align: center; padding: 20px; background: white; border-radius: 10px; border: 1px solid #eee;\">\r\n<div style=\"font-size: 30px; margin-bottom: 10px;\">🎓</div>\r\n<strong style=\"display: block; color: #1b5e20; font-size: 14px;\">Kurikulum Bersanad</strong>\r\n<p style=\"font-size: 11px; color: #777;\">Kajian kitab turost yang tersambung langsung ke pengarangnya.</p>\r\n</div>\r\n<div style=\"width: 220px; text-align: center; padding: 20px; background: white; border-radius: 10px; border: 1px solid #eee;\">\r\n<div style=\"font-size: 30px; margin-bottom: 10px;\">🧘</div>\r\n<strong style=\"display: block; color: #1b5e20; font-size: 14px;\">Praktik Thoriqah</strong>\r\n<p style=\"font-size: 11px; color: #777;\">Bimbingan langsung dalam pengamalan dzikir dan adab thoriqah.</p>\r\n</div>\r\n<div style=\"width: 220px; text-align: center; padding: 20px; background: white; border-radius: 10px; border: 1px solid #eee;\">\r\n<div style=\"font-size: 30px; margin-bottom: 10px;\">🏛️</div>\r\n<strong style=\"display: block; color: #1b5e20; font-size: 14px;\">Pusat Riset Tasawuf</strong>\r\n<p style=\"font-size: 11px; color: #777;\">Fasilitas perpustakaan digital khusus manuskrip tasawuf.</p>\r\n</div>\r\n<div style=\"width: 220px; text-align: center; padding: 20px; background: white; border-radius: 10px; border: 1px solid #eee;\">\r\n<div style=\"font-size: 30px; margin-bottom: 10px;\">🌍</div>\r\n<strong style=\"display: block; color: #1b5e20; font-size: 14px;\">Prospek Karir</strong>\r\n<p style=\"font-size: 11px; color: #777;\">Menjadi konselor spiritual, peneliti, dan pengajar profesional.</p>\r\n</div>\r\n</div>\r\n</div>\r\n<div style=\"background-color: #1b5e20; padding: 40px 20px;\">\r\n<h2 style=\"color: #ffd700; text-align: center; font-size: 20px; margin-bottom: 30px; text-transform: uppercase;\">Galeri Kegiatan Akademik</h2>\r\n<div style=\"display: flex; flex-wrap: wrap; gap: 15px; justify-content: center;\">\r\n<div style=\"width: 45%; min-width: 280px; background: #fff; padding: 8px; border-radius: 5px; box-shadow: 0 4px 8px rgba(0,0,0,0.2);\"><img style=\"width: 100%; height: auto; display: block; border-radius: 3px;\" src=\"https://via.placeholder.com/600x400/1b5e20/ffffff?text=Halaqah+Kitab+Kuning\" alt=\"KBM\">\r\n<div style=\"padding: 10px; font-size: 12px; font-weight: bold; color: #1b5e20; text-align: center;\">&nbsp;</div>\r\n<div style=\"padding: 10px; font-size: 12px; font-weight: bold; color: #1b5e20; text-align: center;\">Halaqah &amp; Kajian Kitab Turost</div>\r\n</div>\r\n<div style=\"width: 45%; min-width: 280px; background: #fff; padding: 8px; border-radius: 5px; box-shadow: 0 4px 8px rgba(0,0,0,0.2);\"><img style=\"width: 100%; height: auto; display: block; border-radius: 3px;\" src=\"https://via.placeholder.com/600x400/ffd700/1b5e20?text=Praktik+Dzikir+Thoriqah\" alt=\"Praktik\">\r\n<div style=\"padding: 10px; font-size: 12px; font-weight: bold; color: #1b5e20; text-align: center;\">Praktik Riyadhoah &amp; Dzikir</div>\r\n</div>\r\n</div>\r\n</div>\r\n<div style=\"padding: 20px; text-align: center; background: #f0f0f0; border-top: 1px solid #ddd;\">\r\n<p style=\"font-size: 12px; color: #666; margin: 0;\"><strong>Sekretariat Prodi Tasawuf wa Thoriqotuhu</strong><br>Gedung Rektorat Lt. 2, Kampus Ma\'had Idrisiyyah<br>Email: tasawuf@idrisiyyah.ac.id | Website: ojs.idrisiyyah.ac.id</p>\r\n</div>\r\n</div>','Profil Prodi Tasawuf dan Tarekat Ma\'had Aly Idrisiyyah','','default','published','2026-03-25 09:07:20','2026-08-25 02:19:04'),(7,NULL,'Organisasi & Soft Skills','organisasi-soft-skills','<p><strong>Organisasi &amp; Soft Skills</strong></p>','Organisasi & Soft Skills','','default','published','2026-03-25 09:08:39','2026-08-25 02:19:04'),(8,NULL,'Selayang Pandang','selayang-pandang','<p class=\"MsoNormal\" style=\"text-align: justify;\"><em>Assalamu&rsquo;alaikum Warahmatullahi Wabarakatuh.</em></p>\n<p class=\"MsoNormal\" style=\"text-align: justify;\">&nbsp;</p>\n<p class=\"MsoNormal\" style=\"text-align: justify;\"><strong>Selamat datang di laman resmi SMK Fadris.</strong></p>\n<p class=\"MsoNormal\" style=\"text-align: justify;\">Di bawah naungan Pondok Pesantren Idrisiyyah, kami hadir dengan satu keyakinan: bahwa kecerdasan teknologi (TKJ) dan kemahiran finansial (AKL) haruslah bersandar pada kokohnya akhlak. Kami tidak hanya mencetak tenaga kerja, tapi membentuk pribadi yang Bertasawuf, Maju, Unggul, dan Mendunia.</p>\n<p class=\"MsoNormal\" style=\"text-align: justify;\">&nbsp;</p>\n<p class=\"MsoNormal\" style=\"text-align: justify;\"><strong>Mengapa SMK Fadris?</strong></p>\n<p class=\"MsoNormal\" style=\"text-align: justify;\">Kami memadukan disiplin pesantren dengan standar industri global. Melalui kurikulum berbasis sertifikasi Mikrotik dan Zahir, serta metode belajar kritis HOTS, siswa kami didorong untuk tidak sekadar menghafal, tapi mampu memberi solusi.</p>\n<p class=\"MsoNormal\" style=\"text-align: justify;\">Di sini, asrama bukan sekadar tempat tinggal, melainkan kawah candradimuka untuk melatih kemandirian dan integritas. Kami ingin setiap lulusan kami siap bersaing di panggung dunia tanpa kehilangan jati diri sebagai santri.</p>\n<p class=\"MsoNormal\" style=\"text-align: justify;\">&nbsp;</p>\n<p class=\"MsoNormal\" style=\"text-align: justify;\"><strong>Mari Berkolaborasi!</strong></p>\n<p class=\"MsoNormal\" style=\"text-align: justify;\">Website ini adalah ruang interaksi kita. Silakan jelajahi program unggulan kami dan jangan ragu untuk berdialog dengan kami melalui saluran digital yang tersedia.</p>\n<p class=\"MsoNormal\" style=\"text-align: justify;\">Mari jemput masa depan yang gemilang: Terampil secara Teknis, Mulia secara Karakter.</p>\n<p class=\"MsoNormal\" style=\"text-align: justify;\"><em>Wassalamu&rsquo;alaikum Warahmatullahi Wabarakatuh.</em></p>','Selayang Pandang Ma\'had Aly Idrisiyyah',NULL,'default','published','2026-03-25 12:59:17','2026-08-30 01:23:17'),(9,NULL,'Fasilitas & Galery','fasilitas-galery','<div style=\"font-family: \'Segoe UI\', Roboto, Arial, sans-serif; color: #333; max-width: 1000px; margin: 0 auto; line-height: 1.6; background-color: #ffffff;\">\r\n<div style=\"text-align: center; padding: 40px 20px;\">\r\n<h2 style=\"color: #1b5e20; text-transform: uppercase; letter-spacing: 2px; margin-bottom: 10px; border-bottom: 3px solid #ffd700; display: inline-block; padding-bottom: 5px; font-size: 20px;\">Fasilitas Ma\'had</h2>\r\n<p style=\"color: #666; font-size: 14px; margin-top: 0;\">Sarana pendukung kenyamanan dan kelancaran kegiatan belajar mengajar.</p>\r\n<table style=\"width: 100%; border-collapse: separate; border-spacing: 15px; margin-top: 20px;\">\r\n<tbody>\r\n<tr>\r\n<td style=\"width: 33%; background: #f1f8e9; border-radius: 12px; padding: 20px; border-top: 5px solid #1b5e20; text-align: center; vertical-align: top; border: 1px solid #e0e0e0;\">\r\n<div style=\"font-size: 30px; margin-bottom: 10px;\">🕌</div>\r\n<strong style=\"color: #1b5e20; display: block; margin-bottom: 8px; font-size: 14px;\">Masjid &amp; Mushalla</strong> <span style=\"font-size: 12px; color: #555;\">Pusat kegiatan ibadah dan kajian kitab kuning yang representatif.</span></td>\r\n<td style=\"width: 33%; background: #fffde7; border-radius: 12px; padding: 20px; border-top: 5px solid #ffd700; text-align: center; vertical-align: top; border: 1px solid #e0e0e0;\">\r\n<div style=\"font-size: 30px; margin-bottom: 10px;\">📚</div>\r\n<strong style=\"color: #856404; display: block; margin-bottom: 8px; font-size: 14px;\">Perpustakaan</strong> <span style=\"font-size: 12px; color: #555;\">Koleksi kitab dan buku referensi yang lengkap untuk santri.</span></td>\r\n<td style=\"width: 33%; background: #f1f8e9; border-radius: 12px; padding: 20px; border-top: 5px solid #1b5e20; text-align: center; vertical-align: top; border: 1px solid #e0e0e0;\">\r\n<div style=\"font-size: 30px; margin-bottom: 10px;\">💻</div>\r\n<strong style=\"color: #1b5e20; display: block; margin-bottom: 8px; font-size: 14px;\">Lab Komputer</strong> <span style=\"font-size: 12px; color: #555;\">Fasilitas TI modern untuk menunjang literasi digital santri.</span></td>\r\n</tr>\r\n<tr>\r\n<td style=\"width: 33%; background: #fffde7; border-radius: 12px; padding: 20px; border-top: 5px solid #ffd700; text-align: center; vertical-align: top; border: 1px solid #e0e0e0;\">\r\n<div style=\"font-size: 30px; margin-bottom: 10px;\">🏀</div>\r\n<strong style=\"color: #856404; display: block; margin-bottom: 8px; font-size: 14px;\">Area Olahraga</strong> <span style=\"font-size: 12px; color: #555;\">Lapangan serbaguna untuk menjaga kesehatan fisik santri.</span></td>\r\n<td style=\"width: 33%; background: #f1f8e9; border-radius: 12px; padding: 20px; border-top: 5px solid #1b5e20; text-align: center; vertical-align: top; border: 1px solid #e0e0e0;\">\r\n<div style=\"font-size: 30px; margin-bottom: 10px;\">🏠</div>\r\n<strong style=\"color: #1b5e20; display: block; margin-bottom: 8px; font-size: 14px;\">Asrama Nyaman</strong> <span style=\"font-size: 12px; color: #55